  state: State
  onChanged: () => void
  request?: { cardId: string; k: number } | null
  /** Controlled from the top bar; the sheet keeps its own state otherwise. */
  open?: boolean
  onOpenChange?: (open: boolean) => void
  hideTrigger?: boolean
}) {
  const [openOwn, setOpenOwn] = useState(false)
  const open = openProp ?? openOwn
  const setOpen = (v: boolean) => { setOpenOwn(v); onOpenChange?.(v) }
  const [items, setItems] = useState<Routine[]>([])
  const [draft, setDraft] = useState<{ routine: Routine; preview: Run } | null>(null)
  const [writing, setWriting] = useState<string | null>(null)
  const [error, setError] = useState('')
  // Drafts the voice assistant wrote during a call; "Not now" hides one on this device.
  const [voice, setVoice] = useState<VoiceDraft[]>([])
  const [hidden, setHidden] = useState<Set<string>>(readHidden)
  const [voiceEdits, setVoiceEdits] = useState<Record<string, { routine: Routine; preview: Run }>>({})
  const tested = useRef(new Set<string>())

  const load = useCallback(async () => {
    try {
      const [r, d] = await Promise.all([fetch('/api/routines'), fetch('/api/routines/drafts')])
      if (r.ok) setItems((await r.json()).routines)
      if (d.ok) setVoice(((await d.json()).drafts ?? []).filter((x: VoiceDraft) => x?.routine?.id))
    } catch { /* offline for a moment: keep the last list */ }
    void refreshLive(0)
  }, [])
  // Proposals and "would handle" follow the app's own refresh of the state.
  useEffect(() => { void refreshLive() }, [state.now, state.last_check_at])
  const live = useLive()
  const proposals = pendingOf(live)
  useEffect(() => { void load() }, [load])
  useEffect(() => {
    void load()
    const t = window.setInterval(load, open ? 10000 : 30000)
    return () => clearInterval(t)
  }, [open, load])

  const waiting = voice.filter(
    (d) => !hidden.has(d.routine.id) && !items.some((r) => r.id === d.routine.id) && draft?.routine.id !== d.routine.id,
  )
  // Test each waiting voice draft once on today's inbox (its stored test may be hours old).
  useEffect(() => {
    if (!open) return
    for (const d of waiting) {
      const id = d.routine.id
      if (tested.current.has(id) || voiceEdits[id] || !d.routine.spec) continue
      tested.current.add(id)
      call<{ routine: Routine; preview: Run }>('/api/routines/preview', body(d.routine))
        .then((out) => setVoiceEdits((v) => (v[id] ? v : { ...v, [id]: { routine: { ...d.routine, code: out.routine.code }, preview: out.preview } })))
        .catch(() => { /* keep the stored test run */ })
    }
  }, [open, waiting, voiceEdits])
  function hideDraft(id: string) {
    const next = new Set(hidden).add(id)
    setHidden(next)
    try { localStorage.setItem(HIDDEN_KEY, JSON.stringify([...next])) } catch { /* private mode */ }
  }

  // Asked from the "automate this" offer: open and start drafting right away.
  useEffect(() => {
    if (!request) return
    setOpen(true)
    void suggest(request.cardId)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [request?.k])

  // Decisions made by hand; a card with a routine says so, the card behind an open draft is hidden.
  const automatedBy = new Map(items.filter((r) => r.created_from).map((r) => [r.created_from!, r.name]))
  const drafting = new Set([draft?.routine.created_from, ...waiting.map((d) => d.card_id)])
  const decided = state.cards.filter((c) => c.status in DECIDED && !drafting.has(c.id))
  const active = items.filter((r) => r.enabled).length
  const writingCard = state.cards.find((c) => c.id === writing)
  const forYou = waiting.length + proposals.length
  const cardHead = (id?: string | null) => (id ? tidy(state.cards.find((c) => c.id === id)?.headline) || undefined : undefined)

  async function suggest(cardId: string) {
    setWriting(cardId); setError(''); setDraft(null)
    try {
      setDraft(await call<{ routine: Routine; preview: Run }>('/api/routines/suggest', { card_id: cardId }))
    } catch (e) {
      setError(`The agent could not write a routine: ${(e as Error).message}.`)
    } finally { setWriting(null) }
  }
  async function turnOn() {
    if (!draft) return
    await call('/api/routines', body(draft.routine))
    setDraft(null)
    await load()
  }
  const changed = () => { void load(); onChanged() }

  return (
    <>
      {!hideTrigger && <button
        onClick={() => setOpen(true)}
        title={
          proposals.length ? `Routines: ${proposals.length} waiting for your OK`
            : waiting.length ? `Routines: ${waiting.length} draft${waiting.length === 1 ? '' : 's'} from your call waiting`
            : 'Routines: what the agents do on their own'
        }
        aria-label={forYou ? `Routines, ${forYou} waiting for you` : active ? `Routines, ${active} on` : 'Routines'}
        className="relative inline-flex h-9 cursor-pointer items-center gap-2 whitespace-nowrap rounded-full border border-line bg-white px-2.5 text-sm font-semibold text-ink-2 hover:bg-panel lg:px-3"
      >
        <Workflow size={16} className={active ? 'text-ok' : ''} />
        <span className="hidden lg:inline">Routines</span>
        {forYou > 0 ? (
          <span className="absolute -right-1 -top-1 grid h-4 min-w-4 place-items-center rounded-full bg-routine px-1 text-[10px] font-bold text-white ring-2 ring-white">{forYou}</span>
        ) : active > 0 && (
          <span className="absolute -right-1 -top-1 grid h-4 min-w-4 place-items-center rounded-full bg-white px-1 text-[10px] font-bold text-ok ring-1 ring-ok/40">{active}</span>
        )}
      </button>}
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent className="sm:max-w-[560px]">
          <div className="border-b border-line px-6 pb-4 pt-6 pr-14">
            <SheetTitle className="text-xl font-bold leading-snug">Routines</SheetTitle>
            <SheetDescription className="mt-1 text-sm text-ink-2">
              Written by an agent from your decisions. They run in a closed sandbox on every check. Anything that costs money or changes the plan still comes to you.
            </SheetDescription>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto px-6 py-5">
            {proposals.length > 0 && (
              <section className="space-y-2" aria-label="Waiting for your OK">
                <h3 className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-routine">
                  <CircleCheck size={13} /> Waiting for your OK · {proposals.length}
                </h3>
                {proposals.map((p) => (
                  <ProposalItem key={p.id} p={p} context={cardHead(p.card_id) ?? (p.shipment_id ? `Shipment ${p.shipment_id}` : undefined)} onDone={onChanged} />
                ))}
              </section>
            )}
            {waiting.length > 0 && (
              <h3 className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-ok">
                <Phone size={13} /> Drafted from your call
              </h3>
            )}
            {waiting.map((d) => {
              const id = d.routine.id
              const cur = voiceEdits[id] ?? { routine: d.routine, preview: d.preview ?? { at: d.at ?? '', ok: true, dry: true } }
              return (
                <div key={`voice-${id}`} className="space-y-2">
                  {d.instruction && <p className="text-sm text-ink-2">You said: “{d.instruction}”</p>}
                  <RoutineCard
                    routine={cur.routine}
                    onChanged={changed}
                    draft={{
                      preview: cur.preview,
                      onTurnOn: async () => { await call('/api/routines', body(cur.routine)); hideDraft(id); await load() },
                      onDiscard: () => hideDraft(id),
                      onReplace: (routine, preview) => setVoiceEdits((v) => ({ ...v, [id]: { routine, preview } })),
                    }}
                  />
                </div>
              )
            })}
            {writing && (
              <div className="rounded-xl border-2 border-dashed border-ok/40 bg-ok/5 p-4 text-[15px]">
                <div className="flex items-center gap-2 font-semibold text-ok">
                  <Loader2 size={16} className="animate-spin" /> The agent is writing a routine from your decision…
                </div>
                {writingCard && (
                  <p className="mt-1 text-ink-2">
                    “{writingCard.headline}”. It builds the steps, checks them in the sandbox and tests them on today's inbox before you see them. This takes up to half a minute.
                  </p>
                )}
              </div>
            )}
            {draft && (
              <RoutineCard
                key={`draft-${draft.routine.id}`}
                routine={draft.routine}
                onChanged={changed}
                draft={{
                  preview: draft.preview,
                  onTurnOn: turnOn,
                  onDiscard: () => setDraft(null),
                  onReplace: (routine, preview) => setDraft({ routine, preview }),
                }}
              />
            )}
            {error && <p className="rounded-lg bg-stop/10 p-3 text-sm text-stop">{error}</p>}

            {items.length > 0 && <h3 className="pt-1 text-xs font-semibold uppercase tracking-wide text-ink-3">Your routines</h3>}
            {items.length === 0 && !draft && !writing && (
              <p className="text-[15px] text-ink-2">No routines yet. Decide a card, then let the agent handle the next one like it.</p>
            )}
            {items.map((r) => <RoutineCard key={r.id} routine={r} onChanged={changed} />)}

            <h3 className="pt-3 text-xs font-semibold uppercase tracking-wide text-ink-3">Automate a decision you made</h3>
            {decided.length === 0 && (
              <p className="text-sm text-ink-3">{draft ? 'Review the suggestion above.' : 'Nothing decided yet.'}</p>
            )}
            <div className="space-y-2">
              {decided.map((c) => (
                <div key={c.id} className="flex items-center justify-between gap-3 rounded-lg border border-line px-3 py-2.5">
                  <div className="min-w-0">
                    <div className="line-clamp-2 text-[15px] font-medium leading-snug">{c.headline}</div>
                    <div className="mt-0.5 text-xs text-ink-3">
                      {DECIDED[c.status]}{c.ui?.at ? ` · ${fmtDay(c.ui.at)} ${fmtTime(c.ui.at)}` : ''}
                    </div>
                  </div>
                  {automatedBy.has(c.id) ? (
                    <span className="max-w-[45%] shrink-0 text-right text-sm font-semibold text-ok">Automated · {automatedBy.get(c.id)}</span>
                  ) : (
                    <Button size="sm" variant="outline" className="shrink-0" disabled={!!writing} onClick={() => suggest(c.id)}>
                      <Sparkles size={14} /> {writing === c.id ? 'Writing…' : 'Automate cards like this'}
                    </Button>
                  )}
                </div>
              ))}
            </div>
          </div>
        </SheetContent>
      </Sheet>
    </>
  )
}
import { useSyncExternalStore } from 'react'
import { call, type Mode, type Proposal, type WouldHandle } from './types'

// What the routines prepared for the buyer, shared by the Routines sheet, the decision pane and
// the inbox list: proposals waiting for an OK, routines that would handle a card, and actions
// undone on this screen. Refreshed on the app's own refresh (see `refreshLive`), never on its
// own timer. Endpoints that are not there yet (404) simply count as empty.

interface Live {
  proposals: Proposal[]
  would: Record<string, WouldHandle[]>
  /** Action id -> "undone" or the reason it could not be undone. */
  undo: Record<string, { ok: boolean; reason?: string }>
  /** Proposals the buyer just accepted or skipped, hidden before the server agrees. */
  settled: Set<string>
}

let live: Live = { proposals: [], would: {}, undo: {}, settled: new Set() }
const subs = new Set<() => void>()
const set = (next: Partial<Live>) => { live = { ...live, ...next }; subs.forEach((f) => f()) }
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f) } }

async function getJson<T>(url: string): Promise<T | null> {
  try {
    const r = await fetch(url)
    return r.ok ? ((await r.json()) as T) : null
  } catch { return null }
}

let lastAt = 0
let inflight: Promise<void> | null = null
/** Fetch proposals and would-handle; calls within `minMs` of the last one are skipped. */
export function refreshLive(minMs = 4000): Promise<void> {
  if (inflight) return inflight
  if (Date.now() - lastAt < minMs) return Promise.resolve()
  lastAt = Date.now()
  inflight = (async () => {
    const [p, w] = await Promise.all([
      getJson<{ proposals?: Proposal[] }>('/api/routines/proposals'),
      getJson<Record<string, WouldHandle[]>>('/api/routines/would-handle'),
    ])
    const proposals = Array.isArray(p?.proposals) ? p.proposals.filter((x) => x && x.id) : []
    const would: Record<string, WouldHandle[]> = {}
    for (const [k, v] of Object.entries(w ?? {})) if (Array.isArray(v) && v.length) would[k] = v
    // Forget settled ids the server no longer lists as pending.
    const pending = new Set(proposals.filter((x) => x.status === 'pending').map((x) => x.id))
    const settled = new Set([...live.settled].filter((id) => pending.has(id)))
    set({ proposals, would, settled })
  })().finally(() => { inflight = null })
  return inflight
}

export function useLive(): Live {
  return useSyncExternalStore(subscribe, () => live)
}

/** Pending proposals not yet answered on this screen; for one card when `cardId` is given. */
export function pendingOf(l: Live, cardId?: string): Proposal[] {
  return l.proposals.filter(
    (p) => (p.status ?? 'pending') === 'pending' && !l.settled.has(p.id) && (cardId == null || p.card_id === cardId),
  )
}

export async function answerProposal(id: string, how: 'accept' | 'skip'): Promise<void> {
  await call(`/api/routines/proposals/${encodeURIComponent(id)}/${how}`)
  // An accepted one stays a moment so its "Done" shows.
  window.setTimeout(() => {
    set({ settled: new Set(live.settled).add(id) })
    lastAt = 0
    void refreshLive()
  }, how === 'accept' ? 1500 : 0)
}

/** Undo a routine's action; remembers the outcome so the list and the pane agree. */
export async function undoAction(actionId: string): Promise<{ ok: boolean; reason?: string }> {
  let out: { ok: boolean; reason?: string }
  try {
    const r = await call<{ ok?: boolean; undone?: boolean; reason?: string }>(`/api/routines/actions/${encodeURIComponent(actionId)}/undo`)
    out = r.ok && r.undone !== false ? { ok: true } : { ok: false, reason: r.reason || 'This can no longer be undone.' }
  } catch (e) {
    const m = (e as Error).message
    out = { ok: false, reason: /404|not found/i.test(m) ? 'Undo is not available yet.' : m }
  }
  set({ undo: { ...live.undo, [actionId]: out } })
  return out
}

export async function setMode(routineId: string, mode: Mode): Promise<void> {
  await call(`/api/routines/${encodeURIComponent(routineId)}/mode`, { mode })
  lastAt = 0
  void refreshLive()
}

export async function setEnabled(routineId: string, enabled: boolean): Promise<void> {
  await call(`/api/routines/${encodeURIComponent(routineId)}/toggle`, { enabled })
  lastAt = 0
  void refreshLive()
}
import { Check, Loader2, Workflow } from 'lucide-react'
import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { tidy } from '@/lib/api'
import { cn } from '@/lib/utils'
import { answerProposal } from './live'
import { StepIcon } from './RoutineFlow'
import type { Proposal, StepKind } from './types'

// One thing a routine in "ask me" mode prepared: what it would do, the text it would send, and
// one tap to do it or skip it. In the sheet it names the card; in the pane it names the routine.

const KNOWN: StepKind[] = ['carry_out', 'notify', 'log', 'chase', 'call', 'ask_status']
const kindOf = (p: Proposal): StepKind => (KNOWN.includes(p.step?.do as StepKind) ? (p.step.do as StepKind) : 'carry_out')

/** "Chase once in the same thread", from the step, with a fallback per kind. */
function proposalWhat(p: Proposal): string {
  const t = tidy(p.step?.text)
  if (t) return t
  const k = kindOf(p)
  return k === 'chase' ? 'Chase once in the same thread'
    : k === 'call' ? 'Call you'
    : k === 'ask_status' ? 'Ask the supplier for a status'
    : k === 'notify' ? 'Tell you'
    : 'Send the prepared message'
}

export function ProposalItem({
  p, context, inPane, onDone,
}: { p: Proposal; context?: string; inPane?: boolean; onDone?: () => void }) {
  const [busy, setBusy] = useState<'accept' | 'skip' | null>(null)
  const [error, setError] = useState('')
  const [done, setDone] = useState(false)
  const kind = kindOf(p)
  const what = proposalWhat(p)

  async function answer(how: 'accept' | 'skip') {
    setBusy(how); setError('')
    try {
      await answerProposal(p.id, how)
      if (how === 'accept') setDone(true)
      onDone?.()
    } catch (e) {
      const why = (e as Error).message
      setError(/404|not found/i.test(why) ? 'This suggestion is gone; the routine may have dropped it.' : `Could not do it: ${why}.`)
    } finally { setBusy(null) }
  }

  return (
    <div className={cn('rounded-xl border border-routine/30 bg-routine/5 p-3.5', inPane && 'p-4')} aria-live="polite">
      <div className="flex items-start gap-3">
        <span className={cn('grid h-8 w-8 shrink-0 place-items-center rounded-lg', kind === 'call' ? 'bg-routine' : 'bg-white ring-1 ring-routine/25')}>
          <StepIcon step={{ do: kind, channel: p.step?.channel }} size={15} className={kind === 'call' ? 'text-white' : 'text-routine'} />
        </span>
        <div className="min-w-0 flex-1">
          {inPane ? (
            <div className="text-[15px] leading-snug text-ink">
              <span className="text-ink-2">Your routine ‘{p.routine_name}’ suggests: </span>
              <span className="font-semibold">{what}</span>
            </div>
          ) : (
            <>
              <div className="flex items-center gap-1 text-xs font-semibold text-routine">
                <Workflow size={12} className="shrink-0" /> <span className="truncate">{p.routine_name}</span>
              </div>
              <div className="mt-0.5 text-[15px] font-semibold leading-snug text-ink">{what}</div>
              {context && <div className="mt-0.5 line-clamp-1 text-sm text-ink-3">{context}</div>}
            </>
          )}
          {p.preview_text && (
            <blockquote className="mt-2 line-clamp-4 whitespace-pre-line border-l-2 border-routine/30 pl-2.5 text-sm leading-relaxed text-ink-2">
              {p.preview_text}
            </blockquote>
          )}
          {error && <p className="mt-2 text-sm text-stop">{error}</p>}
          <div className="mt-3 flex flex-wrap items-center gap-2">
            {done ? (
              <span className="inline-flex items-center gap-1.5 text-sm font-semibold text-routine"><Check size={15} /> Done</span>
            ) : (
              <>
                <Button size="sm" className="bg-routine hover:bg-routine/90" disabled={!!busy} onClick={() => answer('accept')}>
                  {busy === 'accept' ? <Loader2 size={14} className="animate-spin" /> : <Check size={14} />} Do it
                </Button>
                <Button size="sm" variant="ghost" disabled={!!busy} onClick={() => answer('skip')}>
                  {busy === 'skip' ? 'Skipping…' : 'Skip'}
                </Button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}
import { Loader2, Undo2 } from 'lucide-react'
import { useState } from 'react'
import { cn } from '@/lib/utils'
import { undoAction, useLive } from './live'

// "Undo" for something a routine did on its own. The server decides whether it still can (an
// email that went out cannot be unsent); its reason shows in place of the button.

export function UndoAction({
  actionId, onUndone, className,
}: { actionId: string; onUndone?: () => void; className?: string }) {
  const live = useLive()
  const [busy, setBusy] = useState(false)
  const outcome = live.undo[actionId]

  if (outcome?.ok) {
    return <span className={cn('inline-flex items-center gap-1 text-xs font-semibold text-ink-3', className)}><Undo2 size={12} /> Undone</span>
  }
  return (
    <span className={cn('inline-flex min-w-0 flex-wrap items-center gap-x-2 gap-y-0.5', className)}>
      {!outcome && (
        <button
          type="button"
          disabled={busy}
          onClick={async (e) => {
            e.stopPropagation()
            setBusy(true)
            const out = await undoAction(actionId)
            setBusy(false)
            if (out.ok) onUndone?.()
          }}
          onKeyDown={(e) => e.stopPropagation()}
          className="inline-flex cursor-pointer items-center gap-1 rounded-md px-1.5 py-0.5 text-xs font-semibold text-ink-2 ring-1 ring-line hover:bg-white hover:text-ink disabled:opacity-60"
        >
          {busy ? <Loader2 size={12} className="animate-spin" /> : <Undo2 size={12} />} Undo
        </button>
      )}
      {outcome && !outcome.ok && <span className="text-xs font-medium text-stop">{outcome.reason}</span>}
    </span>
  )
}
// Shapes of /api/routines (src/ask_soony/routines.py) and small helpers shared by the routine UI.

export type Field =
  | 'evidence' | 'headline' | 'option_action' | 'option_to' | 'supplier_name' | 'kind'
  | 'hours_left' | 'waiting_hours' | 'has_reply' | 'reply_after_launch' | 'silent_hours'
export type Channel = 'phone' | 'teams' | 'both'
/** What a routine looks at on each check. Missing means open decisions. */
export type Trigger = 'decisions' | 'waiting' | 'shipments'
/** How much a routine may do on its own. Missing means "tell". */
export type Mode = 'ask' | 'tell' | 'quiet'
export type StepKind = 'carry_out' | 'notify' | 'log' | 'chase' | 'call' | 'ask_status'

export interface Cond {
  id: string; field: Field; op: 'contains' | 'is' | 'any_of' | 'lt' | 'gt'; value: string | number | boolean; text: string
}
export interface Step {
  id: string
  do: StepKind
  text: string
  match?: { to?: string; action_contains?: string }
  channel?: Channel
  message?: string
}
export interface Spec { on?: Trigger; when: Cond[]; then: Step[] }

export interface Did {
  do: StepKind
  card?: string; shipment?: string; option?: string; text?: string; channel?: Channel; status?: string; dry?: boolean
}
export interface Run { at: string; ok: boolean; dry?: boolean; result?: unknown; error?: string; log?: string[]; did?: Did[] }
export interface Routine {
  id: string; name: string; description: string; spec?: Spec | null; code: string; enabled: boolean
  mode?: Mode
  created_from?: string | null; created_at?: string; runs?: Run[]; handled?: number; note?: string
}

/** Something a routine in "ask me" mode prepared and waits to be confirmed (GET /api/routines/proposals). */
export interface Proposal {
  id: string
  routine_id: string
  routine_name: string
  card_id?: string | null
  shipment_id?: string | null
  step: { do: StepKind | string; text?: string; channel?: Channel; [k: string]: unknown }
  preview_text?: string | null
  created_at?: string
  status: 'pending' | 'done' | 'skipped'
}
/** A routine that matches a card (GET /api/routines/would-handle). */
export interface WouldHandle { routine_id: string; routine_name: string; mode?: Mode; enabled: boolean }

export const MODES: { key: Mode; label: string; hint: string }[] = [
  { key: 'ask', label: 'Ask me', hint: 'Prepares it, you confirm with one tap' },
  { key: 'tell', label: 'Do it and tell me', hint: 'Does it and tells you' },
  { key: 'quiet', label: 'Do it quietly', hint: 'Does it, you see it in Handled for you' },
]
export const modeOf = (r: Pick<Routine, 'mode'>): Mode => (r.mode === 'ask' || r.mode === 'quiet' ? r.mode : 'tell')

/** The trigger node: what the routine looks at, in the buyer's words. */
export function triggerText(on?: Trigger): { title: string; text: string } {
  if (on === 'waiting') return { title: 'Messages still waiting for an answer', text: 'Every portal check, the emails we sent that have no reply yet' }
  if (on === 'shipments') return { title: 'Shipments that stopped updating', text: 'Every portal check, shipments with no new status for a while' }
  return { title: 'Every portal check · open decisions', text: 'New files, replies and open decisions, about every minute' }
}

const hoursWord = (v: unknown) => {
  const n = Number(v)
  if (!Number.isFinite(n)) return String(v)
  return n < 1 ? `${Math.round(n * 60)} min` : `${Math.round(n * 10) / 10} h`
}
const yes = (v: unknown) => v === true || /^(yes|true|1)$/i.test(String(v))

/**
 * A condition as a buyer reads it. The recipe's own text wins; the numeric and yes/no fields get
 * plain words when it is missing, so a field name never reaches the screen.
 */
export function condWords(c: Cond): string {
  if (c.text?.trim()) return c.text
  const more = c.op === 'gt'
  switch (c.field) {
    case 'hours_left': return `${more ? 'More' : 'Less'} than ${hoursWord(c.value)} before the deadline`
    case 'waiting_hours': return `No answer for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
    case 'silent_hours': return `No shipment update for ${more ? 'more' : 'less'} than ${hoursWord(c.value)}`
    case 'has_reply': return yes(c.value) ? 'The supplier has answered' : 'The supplier has not answered yet'
    case 'reply_after_launch': return yes(c.value) ? 'The answer promises a date after launch' : 'The answer promises a date before launch'
    default: return `${c.op === 'contains' ? 'Mentions' : 'Is'} ${String(c.value)}`
  }
}

/** The fields the save, edit and preview endpoints take. */
export const body = (r: Routine) => ({
  id: r.id, name: r.name, description: r.description, spec: r.spec, created_from: r.created_from ?? null,
})

/** POST that keeps the server's reason on failure (FastAPI puts it in `detail`). */
export async function call<T>(url: string, payload: unknown = {}, method = 'POST'): Promise<T> {
  const r = await fetch(url, {
    method, headers: { 'Content-Type': 'application/json' }, body: method === 'DELETE' ? undefined : JSON.stringify(payload),
  })
  if (!r.ok) {
    let reason = ''
    try { reason = String((await r.json()).detail ?? '') } catch { /* not JSON */ }
    throw new Error(reason || `the server answered ${r.status}`)
  }
  return r.json()
}

export const newId = (prefix: string) => `${prefix}${Math.random().toString(36).slice(2, 8)}`

