import { Filter, Lock, Radar } from 'lucide-react'
import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { StepIcon } from './RoutineFlow'
import { condWords, triggerText, type Run, type Spec, type Step } from './types'

// The routine as an automatic flow graph (n8n style), drawn from the recipe alone: trigger →
// one node per condition → one node per step, with the fixed guard as a side path off the step
// that sends. Counters come from the latest run (a test run shows a "Test run" tag).

const REFUSED = 'Needs you, it costs money or changes the plan'

interface Counts { matched: number; byStep: Map<string, string>; guard: number }

function count(spec: Spec, run?: Run): Counts | null {
  if (!run || !run.ok) return null
  const did = run.did ?? []
  const byStep = new Map<string, string>()
  const sent = did.filter((d) => d.do === 'carry_out').length
  const refused = did.filter((d) => d.do === 'notify' && (d.text ?? '').startsWith(REFUSED)).length
  const told = did.filter((d) => d.do === 'notify' && !(d.text ?? '').startsWith(REFUSED))
  const sendTexts = spec.then.filter((s) => s.do === 'carry_out').map((s) => s.text)
  const noted = (run.log ?? []).filter((l) => l && !sendTexts.some((t) => l.startsWith(t))).length
  for (const s of spec.then) {
    if (s.do === 'carry_out' && sent) byStep.set(s.id, `${sent} sent`)
    if (s.do === 'notify') {
      const n = told.filter((d) => d.channel === (s.channel ?? 'both')).length
      if (n) byStep.set(s.id, `${n} told`)
    }
    if (s.do === 'log' && noted) byStep.set(s.id, `${noted} noted`)
    const did_ = (k: Step['do']) => did.filter((d) => d.do === k).length
    if (s.do === 'chase' && did_('chase')) byStep.set(s.id, `${did_('chase')} chased`)
    if (s.do === 'ask_status' && did_('ask_status')) byStep.set(s.id, `${did_('ask_status')} asked`)
    if (s.do === 'call' && did_('call')) byStep.set(s.id, `${did_('call')} called`)
  }
  const handled = typeof run.result === 'number' ? run.result : new Set(did.map((d) => d.card)).size
  return { matched: handled, byStep, guard: refused }
}

function stepTitle(s: Step): string {
  if (s.do === 'carry_out') return 'Send it'
  if (s.do === 'log') return 'Note it'
  if (s.do === 'chase') return 'Chase once'
  if (s.do === 'ask_status') return 'Ask for a status'
  if (s.do === 'call') return 'Call you'
  return s.channel === 'phone' ? 'Tell you on your phone' : s.channel === 'teams' ? 'Tell you on Teams' : 'Tell you'
}

function Node({
  icon, tone, title, text, badge, active, dashed, wide, person,
}: {
  icon: ReactNode; tone: string; title: string; text: string; badge?: string; active?: boolean; dashed?: boolean; wide?: boolean
  /** The step reaches a person (a call): its own emphasis. */
  person?: boolean
}) {
  return (
    <div
      className={cn(
        'relative w-full min-w-0 rounded-xl border p-2.5 shadow-[0_1px_2px_rgba(15,23,42,0.04)]',
        wide && 'lg:w-[210px] lg:shrink-0',
        dashed ? 'border-dashed border-ink-3/40 bg-panel' : person ? 'border-routine/40 bg-routine/5' : 'border-line bg-white',
        active && 'ring-2 ring-emerald-500/35',
      )}
      title={text}
    >

      <div className="flex items-start gap-2.5">
        <div className={cn('grid h-8 w-8 shrink-0 place-items-center rounded-lg', tone)}>{icon}</div>
        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-1.5">
            <div className="line-clamp-2 min-w-0 text-[13px] font-semibold leading-snug text-ink">{title}</div>
            {badge && (
              <span
                className={cn(
                  'shrink-0 whitespace-nowrap rounded-full px-1.5 py-px text-[11px] font-semibold ring-1',
                  active ? 'bg-emerald-50 text-emerald-700 ring-emerald-600/20' : 'bg-panel text-ink-3 ring-line',
                )}
              >
                {badge}
              </span>
            )}
          </div>
          <div className={cn('mt-0.5 line-clamp-2 text-[12.5px] leading-snug text-ink-2', wide && 'lg:line-clamp-3')}>{text}</div>
          {person && <div className="mt-1 text-[11px] font-bold uppercase tracking-wide text-routine">Rings a person</div>}
        </div>
      </div>
    </div>
  )
}

const stroke = (dashed?: boolean) => ({ stroke: 'currentColor', strokeWidth: 1.25, fill: 'none', strokeDasharray: dashed ? '3 3' : undefined })
const Down = ({ dashed }: { dashed?: boolean }) => (
  <svg width="10" height="22" viewBox="0 0 10 22" aria-hidden className="block"><line x1="5" y1="0" x2="5" y2="20" {...stroke(dashed)} /><path d="M1.5 16 L5 21 L8.5 16" {...stroke()} /></svg>
)
const Right = ({ dashed }: { dashed?: boolean }) => (
  <svg width="28" height="10" viewBox="0 0 28 10" aria-hidden className="block"><line x1="0" y1="5" x2="26" y2="5" {...stroke(dashed)} /><path d="M22 1.5 L27 5 L22 8.5" {...stroke()} /></svg>
)

/**
 * A thin line with a small arrow. The main path runs down (narrow) or right (wide view on a large
 * screen); a side branch runs the other way.
 */
function Arrow({ wide, dashed, side }: { wide?: boolean; dashed?: boolean; side?: boolean }) {
  // On a phone the side branch drops below the step instead of beside it.
  const narrow = side ? (
    <>
      <div className="ml-[26px] sm:hidden"><Down dashed={dashed} /></div>
      <div className="mt-[21px] hidden sm:block"><Right dashed={dashed} /></div>
    </>
  ) : <div className="ml-[26px]"><Down dashed={dashed} /></div>
  if (!wide) return <div className="shrink-0 text-ink-3/70">{narrow}</div>
  const large = side ? <div className="ml-[26px]"><Down dashed={dashed} /></div> : <div className="mt-[21px]"><Right dashed={dashed} /></div>
  return (
    <div className="shrink-0 text-ink-3/70">
      <div className="lg:hidden">{narrow}</div>
      <div className="hidden lg:block">{large}</div>
    </div>
  )
}

function nodesFor(spec: Spec, run: Run | undefined, wide: boolean) {
  const c = count(spec, run)
  const guard = (
    <Node
      wide={wide}
      dashed
      icon={<Lock size={15} className="text-ink-2" />}
      tone="bg-white ring-1 ring-line"
      title="You decide"
      text="Costs money or changes the plan? It comes to you."
      badge={c?.guard ? `${c.guard} to you` : undefined}
      active={!!c?.guard}
    />
  )
  const trigger = (
    <Node
      wide={wide}
      icon={<Radar size={15} className="text-ok" />}
      tone="bg-ok/10"
      title={triggerText(spec.on).title}
      text={triggerText(spec.on).text}
      badge={run?.dry ? 'Test run' : undefined}
    />
  )
  const conditions = spec.when.map((cond, i) => ({
    key: cond.id,
    node: (
      <Node
        wide={wide}
        icon={<Filter size={15} className="text-amber-700" />}
        tone="bg-amber-50"
        title={i === 0 ? 'If' : 'And'}
        text={condWords(cond)}
        badge={i === spec.when.length - 1 && c ? `${c.matched} matched` : undefined}
        active={i === spec.when.length - 1 && !!c?.matched}
      />
    ),
  }))
  const steps = spec.then.map((s) => {
    const badge = c?.byStep.get(s.id)
    return {
      key: s.id,
      sends: s.do === 'carry_out',
      node: (
        <Node
          wide={wide}
          icon={<StepIcon step={s} size={15} className={s.do === 'call' ? 'text-white' : undefined} />}
          tone={s.do === 'log' ? 'bg-panel ring-1 ring-line' : s.do === 'call' ? 'bg-routine' : 'bg-ok/10'}
          person={s.do === 'call'}
          title={stepTitle(s)}
          text={s.text}
          badge={badge}
          active={!!badge}
        />
      ),
    }
  })
  return { guard, trigger, conditions, steps }
}

/**
 * The wide view reads like a sentence in two lanes: WHEN (trigger, then every condition) left to
 * right, then a turn down into THEN (the steps) left to right. Lanes wrap instead of running off
 * the edge; the guard hangs below the step it protects, or sits in its own ALWAYS lane.
 */
function Lanes({ spec, run }: { spec: Spec; run?: Run }) {
  const { guard, trigger, conditions, steps } = nodesFor(spec, run, true)
  const hasSend = steps.some((s) => s.sends)
  const chain = (items: { key: string; node: ReactNode }[]) =>
    items.map((it, i) => (
      <div key={it.key} className="flex items-start">
        {i > 0 && <div className="mt-[21px] shrink-0 px-1 text-ink-3/70"><Right /></div>}
        {it.node}
      </div>
    ))
  const lane = (label: string, body: ReactNode, last = false) => (
    <div className="grid grid-cols-[64px_minmax(0,1fr)] gap-x-3">
      <div className="flex flex-col items-center pt-[18px]">
        <span className="text-[11px] font-bold uppercase tracking-wider text-ink-3">{label}</span>
        {!last && (
          <div className="mt-2 flex flex-1 flex-col items-center text-ink-3/70">
            <div className="w-px flex-1 bg-current" />
            <svg width="10" height="7" viewBox="0 0 10 7" aria-hidden className="block"><path d="M1.5 1 L5 6 L8.5 1" {...stroke()} /></svg>
          </div>
        )}
      </div>
      <div className="flex min-w-0 flex-wrap items-start gap-y-5 pb-6">{body}</div>
    </div>
  )
  return (
    <div className="flex flex-col">
      {lane('When', chain([{ key: 'trigger', node: trigger }, ...conditions]))}
      {lane(
        'Then',
        chain(
          steps.map((s) => ({
            key: s.key,
            node: s.sends ? (
              <div className="flex flex-col">
                {s.node}
                <div className="ml-[26px] text-ink-3/70"><Down dashed /></div>
                {guard}
              </div>
            ) : (
              s.node
            ),
          })),
        ),
        hasSend,
      )}
      {!hasSend && lane('Always', guard, true)}
    </div>
  )
}

export function FlowGraph({ spec, run, wide }: { spec: Spec; run?: Run; wide?: boolean }) {
  const { guard, trigger, conditions, steps } = nodesFor(spec, run, false)
  const sendAt = steps.findIndex((s) => s.sends)
  // Narrow: one vertical path; conditions stack (they all have to hold); the step that sends
  // carries the guard as a side branch.
  const columns: { key: string; node: ReactNode }[] = [
    { key: 'trigger', node: trigger },
    {
      key: 'when',
      node: (
        <div className="flex flex-col">
          {conditions.map((cond, i) => (
            <div key={cond.key}>
              {i > 0 && <Arrow />}
              {cond.node}
            </div>
          ))}
        </div>
      ),
    },
    ...steps.map((s, i) => {
      if (i !== sendAt) return { key: s.key, node: s.node }
      return {
        key: s.key,
        node: (
          <div className="flex flex-col sm:flex-row sm:items-start">
            <div className="min-w-0 sm:flex-[3]">{s.node}</div>
            <Arrow side dashed />
            <div className="min-w-0 pl-6 sm:flex-[2] sm:pl-0">{guard}</div>
          </div>
        ),
      }
    }),
  ]
  if (sendAt < 0) columns.push({ key: 'guard', node: guard })
  const vertical = (
    <div className="flex flex-col">
      {columns.map((col, i) => (
        <div key={col.key} className="flex min-w-0 flex-col">
          {i > 0 && <Arrow dashed={col.key === 'guard'} />}
          {col.node}
        </div>
      ))}
    </div>
  )
  if (!wide) return vertical
  return (
    <>
      <div className="hidden lg:block"><Lanes spec={spec} run={run} /></div>
      <div className="lg:hidden">{vertical}</div>
    </>
  )
}

import { BellRing, GripVertical, Lock, MailWarning, MessageSquare, NotebookPen, PackageSearch, Phone, Plus, Radar, Send, Smartphone, X } from 'lucide-react'
import { useState, type DragEvent, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { PALETTE, condWords, paletteKey, triggerText, type Channel, type Cond, type Spec, type Step } from './types'

// One routine as blocks a buyer reads at a glance: WHEN (conditions), THEN (steps in order) and
// the fixed ALWAYS guard. With `before` it shows what a change does, block by block. With
// `onChange` the buyer edits directly: × removes, drag reorders, the palette adds steps.

type Mark = 'same' | 'added' | 'removed' | 'changed'
interface Row<T> { item: T; mark: Mark; old?: T; moved?: boolean }

/** Before and after merged by block id, removed blocks kept at their old place. */
function merge<T extends { id: string; text: string }>(after: T[], before?: T[]): Row<T>[] {
  if (!before) return after.map((item) => ({ item, mark: 'same' }))
  const old = new Map(before.map((b) => [b.id, b]))
  const now = new Set(after.map((a) => a.id))
  const commonBefore = before.filter((b) => now.has(b.id)).map((b) => b.id)
  const commonAfter = after.filter((a) => old.has(a.id)).map((a) => a.id)
  // Removed blocks hang after the last surviving block that preceded them.
  const anchored = new Map<string | null, T[]>()
  let anchor: string | null = null
  for (const b of before) {
    if (now.has(b.id)) { anchor = b.id; continue }
    anchored.set(anchor, [...(anchored.get(anchor) ?? []), b])
  }
  const gone = (key: string | null) => (anchored.get(key) ?? []).map((item): Row<T> => ({ item, mark: 'removed' }))
  const rows: Row<T>[] = gone(null)
  for (const a of after) {
    const b = old.get(a.id)
    const mark: Mark = !b ? 'added' : JSON.stringify(b) === JSON.stringify(a) ? 'same' : 'changed'
    const moved = !!b && commonBefore.indexOf(a.id) !== commonAfter.indexOf(a.id)
    rows.push({ item: a, mark, old: b, moved })
    rows.push(...gone(a.id))
  }
  return rows
}

function Tag({ mark, moved }: { mark: Mark; moved?: boolean }) {
  if (mark === 'added') return <span className="shrink-0 rounded bg-ok px-1.5 py-0.5 text-[11px] font-bold uppercase tracking-wide text-white">New</span>
  if (mark === 'removed') return <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-stop">Removed</span>
  if (mark === 'changed') return <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-ok">Changed</span>
  if (moved) return <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-ok">Moved</span>
  return null
}

function Phrase<T extends { text: string }>({ row, words = (x) => x.text }: { row: Row<T>; words?: (x: T) => string }) {
  const now = words(row.item)
  const was = row.old ? words(row.old) : now
  if (row.mark === 'changed' && was !== now) {
    return (
      <span>
        <span className="text-ink-3 line-through">{was}</span>{' '}
        <span>{now}</span>
      </span>
    )
  }
  return <span className={cn(row.mark === 'removed' && 'line-through')}>{now}</span>
}

const markClass = (m: Mark) =>
  m === 'added' ? 'bg-ok/5 ring-1 ring-ok/40' : m === 'removed' ? 'opacity-60' : m === 'changed' ? 'ring-1 ring-ok/40' : ''

export function StepIcon({ step, size = 16, className }: { step: Pick<Step, 'do' | 'channel'>; size?: number; className?: string }) {
  if (step.do === 'carry_out') return <Send size={size} className={className ?? 'text-ok'} />
  if (step.do === 'log') return <NotebookPen size={size} className={className ?? 'text-ink-3'} />
  if (step.do === 'chase') return <MailWarning size={size} className={className ?? 'text-ok'} />
  if (step.do === 'ask_status') return <PackageSearch size={size} className={className ?? 'text-ok'} />
  // A call reaches a person: it carries the routine colour wherever it shows.
  if (step.do === 'call') return <Phone size={size} className={className ?? 'text-routine'} />
  return <ChannelIcon channel={step.channel} size={size} />
}

export function ChannelIcon({ channel, size = 16 }: { channel?: Channel; size?: number }) {
  if (channel === 'phone') return <Smartphone size={size} className="text-ok" />
  if (channel === 'teams') return <MessageSquare size={size} className="text-ok" />
  return <BellRing size={size} className="text-ok" />
}

const Connector = () => <div aria-hidden className="ml-6 h-3 w-px bg-line" />

function Block({ label, tone, children, className }: { label: string; tone?: 'ok'; children: ReactNode; className?: string }) {
  return (
    <div className={cn('rounded-lg border border-line bg-white px-3 py-2.5', className)}>
      <div className={cn('mb-2 text-xs font-bold uppercase tracking-wide', tone === 'ok' ? 'text-ok' : 'text-ink-3')}>{label}</div>
      {children}
    </div>
  )
}

function RemoveButton({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={label}
      title={label}
      className="grid h-5 w-5 shrink-0 cursor-pointer place-items-center rounded text-ink-3 opacity-0 transition-opacity hover:bg-stop/10 hover:text-stop focus-visible:opacity-100 group-hover:opacity-100"
    >
      <X size={13} />
    </button>
  )
}

type Drag = { kind: 'step'; id: string } | { kind: 'palette'; key: string }

export function RoutineFlow({
  spec, before, onChange, disabled,
}: { spec: Spec; before?: Spec; onChange?: (spec: Spec) => void; disabled?: boolean }) {
  const editable = !!onChange && !disabled
  const when = merge<Cond>(spec.when, before?.when)
  const then = merge<Step>(spec.then, before?.then)
  const [drag, setDrag] = useState<Drag | null>(null)
  const [dropAt, setDropAt] = useState<number | null>(null)
  const present = new Set(spec.then.map(paletteKey).filter(Boolean))
  const palette = PALETTE.filter((p) => !present.has(p.key))

  const change = (next: Partial<Spec>) => onChange?.({ ...spec, ...next })
  const removeCond = (id: string) => change({ when: spec.when.filter((c) => c.id !== id) })
  const removeStep = (id: string) => change({ then: spec.then.filter((s) => s.id !== id) })
  const addStep = (key: string, at = spec.then.length) => {
    const p = PALETTE.find((x) => x.key === key)
    if (!p) return
    const steps = [...spec.then]
    steps.splice(at, 0, p.make())
    change({ then: steps })
  }

  function readDrag(e: DragEvent): Drag | null {
    if (drag) return drag
    try { return JSON.parse(e.dataTransfer.getData('text/plain')) as Drag } catch { return null }
  }
  function start(e: DragEvent, d: Drag) {
    e.dataTransfer.setData('text/plain', JSON.stringify(d))
    e.dataTransfer.effectAllowed = d.kind === 'step' ? 'move' : 'copy'
    setDrag(d)
  }
  function end() { setDrag(null); setDropAt(null) }
  function over(e: DragEvent, index: number) {
    if (!editable) return
    e.preventDefault()
    e.stopPropagation() // the list's own handler would move the drop point to the end
    const box = (e.currentTarget as HTMLElement).getBoundingClientRect()
    setDropAt(e.clientY < box.top + box.height / 2 ? index : index + 1)
  }
  function drop(e: DragEvent) {
    e.preventDefault()
    const d = readDrag(e)
    const at = dropAt ?? spec.then.length
    end()
    if (!d || !editable) return
    if (d.kind === 'palette') return addStep(d.key, at)
    const from = spec.then.findIndex((s) => s.id === d.id)
    if (from < 0) return
    const steps = [...spec.then]
    const [moved] = steps.splice(from, 1)
    steps.splice(at > from ? at - 1 : at, 0, moved)
    if (steps.some((s, i) => s.id !== spec.then[i].id)) change({ then: steps })
  }

  // Position of each live step in `spec.then`, for drop targets (removed rows have none).
  const indexOf = new Map(spec.then.map((s, i) => [s.id, i]))
  const indicator = <div aria-hidden className="my-0.5 h-0.5 rounded-full bg-ok" />

  return (
    <div>
      <Block label="When">
        <div className="mb-2 flex items-center gap-1.5 text-sm font-medium text-ink">
          <Radar size={14} className="shrink-0 text-ok" />
          {triggerText(spec.on).title}
          {before && before.on !== spec.on && <Tag mark="changed" />}
        </div>
        <div className="flex flex-wrap gap-1.5">
          {when.map((row) => (
            <span
              key={row.item.id}
              className={cn(
                'group inline-flex max-w-full items-start gap-1.5 rounded-md bg-panel px-2 py-1 text-sm leading-snug text-ink ring-1 ring-line',
                markClass(row.mark),
              )}
            >
              <Phrase row={row} words={condWords} />
              <Tag mark={row.mark} moved={false} />
              {editable && row.mark !== 'removed' && (
                <RemoveButton label="Remove this condition" onClick={() => removeCond(row.item.id)} />
              )}
            </span>
          ))}
        </div>
      </Block>
      <Connector />
      <Block label="Then" tone="ok">
        <ol
          className="space-y-1"
          onDragOver={(e) => { if (editable) { e.preventDefault(); if (dropAt == null) setDropAt(spec.then.length) } }}
          onDrop={drop}
          onDragLeave={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setDropAt(null) }}
        >
          {then.map((row) => {
            const i = indexOf.get(row.item.id)
            const live = row.mark !== 'removed' && i != null
            return (
              <li key={row.item.id}>
                {live && dropAt === i && drag && indicator}
                <div
                  draggable={editable && live}
                  onDragStart={(e) => start(e, { kind: 'step', id: row.item.id })}
                  onDragEnd={end}
                  onDragOver={(e) => live && over(e, i)}
                  className={cn(
                    'group flex items-start gap-2 rounded-md px-1.5 py-1.5 text-[15px] leading-snug',
                    markClass(row.mark),
                    editable && live && 'cursor-grab hover:bg-panel active:cursor-grabbing',
                    row.item.do === 'call' && row.mark === 'same' && 'bg-routine/5 ring-1 ring-routine/25',
                    drag?.kind === 'step' && drag.id === row.item.id && 'opacity-40',
                  )}
                >
                  {editable && (
                    <GripVertical size={14} className={cn('mt-0.5 shrink-0 text-ink-3 opacity-0', live && 'group-hover:opacity-100')} />
                  )}
                  <span className="mt-0.5 shrink-0"><StepIcon step={row.item} /></span>
                  <span className="min-w-0 flex-1">
                    <Phrase row={row} />
                    {row.item.do === 'call' && <span className="mt-0.5 block text-xs font-semibold text-routine">Rings a person</span>}
                  </span>
                  <Tag mark={row.mark} moved={row.moved} />
                  {editable && live && <RemoveButton label="Remove this step" onClick={() => removeStep(row.item.id)} />}
                </div>
              </li>
            )
          })}
          {dropAt === spec.then.length && drag && <li>{indicator}</li>}
        </ol>
        {editable && palette.length > 0 && (
          <div className="mt-2 flex flex-wrap items-center gap-1.5 border-t border-dashed border-line pt-2">
            <span className="mr-0.5 text-xs text-ink-3">Add a step</span>
            {palette.map((p) => (
              <button
                key={p.key}
                type="button"
                draggable
                onDragStart={(e) => start(e, { kind: 'palette', key: p.key })}
                onDragEnd={end}
                onClick={() => addStep(p.key)}
                title="Click to add, or drag it into place"
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-dashed border-ok/50 bg-white px-2.5 py-1 text-[13px] font-medium text-ink-2 hover:border-ok hover:bg-ok/5 hover:text-ink"
              >
                <Plus size={12} className="text-ok" />
                <StepIcon step={p.make()} size={13} />
                {p.label}
              </button>
            ))}
          </div>
        )}
      </Block>
      <Connector />
      <div className="flex items-start gap-2.5 rounded-lg border border-dashed border-line bg-panel px-3 py-2.5">
        <Lock size={15} className="mt-0.5 shrink-0 text-ink-3" />
        <div>
          <div className="text-xs font-bold uppercase tracking-wide text-ink-3">Always</div>
          <div className="mt-0.5 text-[15px] text-ink-2">Costs money or changes the plan? It comes to you.</div>
        </div>
      </div>
    </div>
  )
}

