@import "tailwindcss";

@theme {
  /* Instrument Sans (index.html), one typeface for everything. */
  --font-sans: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --color-ground: #fbfbfa;
  --color-ink: #18181a;
  --color-ink-2: #5d5d63;
  --color-ink-3: #93939a;
  --color-line: #ececea;
  --color-hair: #ececea;
  --color-panel: #f3f3f1;
  --color-soft: #f3f3f1;
  /* The one blue: the primary button and the selected item. */
  --color-ok: #2348d0;
  --color-accent: #2348d0;
  --color-warn: #b45309;
  /* Only the late or short number. */
  --color-stop: #c8321f;
  --color-late: #c8321f;
  --color-silent: #93939a;
  /* Work a routine did on its own. */
  --color-routine: #16795d;
  /* A supplier answered. */
  --color-good: #16795d;
  /* The highlighter: only on source crops. */
  --color-mark: #ffe066;
  --color-land: #eceff3;
}

html, body, #root { height: 100%; }
body {
  background: var(--color-ground);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

@keyframes pulse-ring {
  0% { r: 5px; opacity: .9; }
  100% { r: 20px; opacity: 0; }
}
.pulse-ring { animation: pulse-ring 1.6s ease-out infinite; }
.pulse-once { animation: pulse-ring 1.2s ease-out 3; }
.pulse-once.delay { animation-delay: .5s; }

@keyframes recolour {
  0% { stroke-width: 7px; }
  100% { stroke-width: 2.75px; }
}
.route-recolour { animation: recolour 1.2s ease-out; }

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-14px); }
  to { opacity: 1; transform: none; }
}
.slide-in { animation: slide-in .45s ease-out; }

@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}
.toast-in { animation: toast-in .25s ease-out; }

/* Detail pane: fade the next decision in instead of jumping. */
@keyframes pane-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
.pane-in { animation: pane-in .2s ease-out; }

.scroll-thin { scrollbar-width: thin; scrollbar-color: var(--color-line) transparent; }

kbd {
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 5px;
  border: 1px solid var(--color-line);
  border-bottom-width: 2px;
  background: #fff;
  color: var(--color-ink-2);
}

/* The Routines button (Routines.tsx) dressed as a header tab or a menu row. Unlayered, so it
   wins over the button's own utilities without touching that component. */
.tab-routines > button {
  height: 2rem;
  border: 0;
  border-radius: 6px;
  background: transparent;
  padding: 0 12px;
}
.tab-routines > button:hover { background: transparent; color: var(--color-ink); }
.tab-routines-menu > button {
  width: 100%;
  height: 2.5rem;
  justify-content: flex-start;
  border: 0;
  border-radius: 8px;
  padding: 0 8px;
  font-size: 15px;
}
.tab-routines-menu > button > span.hidden { display: inline; }

/* Today: three sizes per viewport. */
:root { --big: 27px; --body: 17px; --small: 13px; }
@media (min-width: 1024px) { :root { --big: 34px; --body: 18px; --small: 13.5px; } }

.t-big { font-size: var(--big); line-height: 1.2; font-weight: 600; letter-spacing: -0.025em; }
.t-body { font-size: var(--body); line-height: 1.6; }
.t-small { font-size: var(--small); line-height: 1.5; }

/* A grounded number: dotted underline, tap to see where it was read. */
.cite {
  color: var(--color-ink); font-weight: 500; cursor: pointer;
  border-bottom: 1.5px dotted var(--color-ink-3); padding-bottom: 1px;
  background: none; font: inherit; font-weight: 500; text-align: left;
}
.cite.late { color: var(--color-late); border-bottom-color: color-mix(in srgb, var(--color-late) 55%, transparent); }
.cite:hover, .cite[aria-expanded="true"] { border-bottom-style: solid; }
.cite:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; border-radius: 2px; }
.cite svg { display: inline; width: 13px; height: 13px; margin-left: 3px; color: var(--color-ink-3); vertical-align: 0; }

.uline { color: var(--color-ink-2); border-bottom: 1px solid var(--color-hair); cursor: pointer; }
.uline:hover { color: var(--color-ink); border-bottom-color: var(--color-ink-3); }
.uline:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.dot-routine::before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--color-routine); margin-right: 8px; vertical-align: 2px; }

@keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.rise { animation: rise .28s ease-out; }
@keyframes sheet-up { from { transform: translateY(24px); opacity: 0; } to { transform: none; opacity: 1; } }
.sheet-up { animation: sheet-up .22s ease-out; }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
.fade { animation: fade .2s ease-out; }
@media (prefers-reduced-motion: reduce) { .rise, .sheet-up, .fade, .pane-in, .slide-in { animation: none; } }
import { Loader2, Workflow } from 'lucide-react'
import { useState } from 'react'
import type { Card } from '@/lib/api'
import { cn } from '@/lib/utils'
import { pendingOf, setEnabled, setMode, useLive } from './live'
import { ProposalItem } from './Proposals'
import { modeOf, type WouldHandle } from './types'

// What the buyer's routines say about the card in the decision pane: a step one of them
// prepared and waits to be confirmed, or a routine that would handle this card if it were on.

export function PaneHints({ card, onChanged }: { card: Card; onChanged: () => void }) {
  const live = useLive()
  const proposals = pendingOf(live, card.id)
  const asking = new Set(proposals.map((p) => p.routine_id))
  const would = card.status === 'open' ? (live.would[card.id] ?? []).filter((w) => !asking.has(w.routine_id)) : []
  if (!proposals.length && !would.length) return null
  return (
    <div className="space-y-2">
      {proposals.map((p) => <ProposalItem key={p.id} p={p} inPane onDone={onChanged} />)}
      {would.map((w) => <WouldChip key={w.routine_id} w={w} onChanged={onChanged} />)}
    </div>
  )
}

function WouldChip({ w, onChanged }: { w: WouldHandle; onChanged: () => void }) {
  const [busy, setBusy] = useState<'on' | 'ask' | null>(null)
  const [error, setError] = useState('')
  const mode = modeOf(w)

  async function go(kind: 'on' | 'ask') {
    setBusy(kind); setError('')
    try {
      if (!w.enabled) await setEnabled(w.routine_id, true)
      await setMode(w.routine_id, kind === 'on' ? 'tell' : 'ask')
      onChanged()
    } catch (e) {
      const why = (e as Error).message
      setError(/404|not found/i.test(why) ? 'Not available on the server yet.' : why)
    } finally { setBusy(null) }
  }

  const text = !w.enabled
    ? <>Your routine ‘{w.routine_name}’ would handle this</>
    : mode === 'ask'
      ? <>Your routine ‘{w.routine_name}’ will ask you about this on the next check</>
      : <>Your routine ‘{w.routine_name}’ handles this on the next check</>

  return (
    <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5 rounded-lg px-3 py-2 text-sm ring-1 ring-routine/25">
      <span className="inline-flex min-w-0 items-center gap-1.5 text-ink-2">
        <Workflow size={14} className="shrink-0 text-routine" />
        <span className="min-w-0">{text}</span>
      </span>
      <span className="ml-auto inline-flex items-center gap-1">
        {!w.enabled && (
          <ChipButton busy={busy === 'on'} disabled={!!busy} onClick={() => go('on')} strong>Turn it on</ChipButton>
        )}
        {(!w.enabled || mode !== 'ask') && (
          <ChipButton busy={busy === 'ask'} disabled={!!busy} onClick={() => go('ask')}>Let it ask me first</ChipButton>
        )}
      </span>
      {error && <span className="basis-full text-xs text-stop">{error}</span>}
    </div>
  )
}

function ChipButton({
  children, busy, disabled, onClick, strong,
}: { children: string; busy?: boolean; disabled?: boolean; onClick: () => void; strong?: boolean }) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={cn(
        'inline-flex cursor-pointer items-center gap-1 whitespace-nowrap rounded-md px-2 py-1 text-[13px] font-semibold disabled:opacity-60',
        strong ? 'text-routine hover:bg-routine/10' : 'text-ink-2 hover:bg-panel hover:text-ink',
      )}
    >
      {busy && <Loader2 size={12} className="animate-spin" />} {children}
    </button>
  )
}
import { Loader2, Undo2 } from 'lucide-react'
import { useState } from 'react'
import { cn } from '@/lib/utils'
import { undoAction, useLive } from './live'

// "Undo" for something a routine did on its own. The server decides whether it still can (an
// email that went out cannot be unsent); its reason shows in place of the button.

export function UndoAction({
  actionId, onUndone, className,
}: { actionId: string; onUndone?: () => void; className?: string }) {
  const live = useLive()
  const [busy, setBusy] = useState(false)
  const outcome = live.undo[actionId]

  if (outcome?.ok) {
    return <span className={cn('inline-flex items-center gap-1 text-xs font-semibold text-ink-3', className)}><Undo2 size={12} /> Undone</span>
  }
  return (
    <span className={cn('inline-flex min-w-0 flex-wrap items-center gap-x-2 gap-y-0.5', className)}>
      {!outcome && (
        <button
          type="button"
          disabled={busy}
          onClick={async (e) => {
            e.stopPropagation()
            setBusy(true)
            const out = await undoAction(actionId)
            setBusy(false)
            if (out.ok) onUndone?.()
          }}
          onKeyDown={(e) => e.stopPropagation()}
          className="inline-flex cursor-pointer items-center gap-1 rounded-md px-1.5 py-0.5 text-xs font-semibold text-ink-2 ring-1 ring-line hover:bg-white hover:text-ink disabled:opacity-60"
        >
          {busy ? <Loader2 size={12} className="animate-spin" /> : <Undo2 size={12} />} Undo
        </button>
      )}
      {outcome && !outcome.ok && <span className="text-xs font-medium text-stop">{outcome.reason}</span>}
    </span>
  )
}
